/* Progression, tableau de bord contextuel, portraits et tests de compétence. */
const navUnlock={life:0,actions:6,projects:8,career:18,money:18,people:5,family:18,journal:0};
function unlockedTab(id){return !state||state.person.age>=(navUnlock[id]||0)||(id==='family'&&state.generation>1)}
function visibleTabs(){return tabs.filter(([id])=>unlockedTab(id))}
const progressiveNav=nav;nav=function(id){if(!unlockedTab(id)){toast('Cette partie de la vie se découvre à '+navUnlock[id]+' ans.');return}progressiveNav(id)};
const gatedAction=Life.action;Life.action=function(s,type,value){const limits={learn:6,sport:6,social:5,prepare:16,network:14,gig:18,scholarship:16,insurance:18,familyPolicy:18,donate:18,person:5,lifestyle:18,saving:18,businessStrategy:18};if(s.person.age<(limits[type]||0))return{ok:false,message:'Cette possibilité se débloque à '+limits[type]+' ans.'};return gatedAction(s,type,value)};
function avatarPerson(name){if(!state)return{name,id:name,age:28};return Object.values(state.people).find(x=>x.name+' '+x.surname===name||x.name===name)||state.person.friends.find(x=>x.name===name)||state.person.parents.find(x=>x.name===name)||{name,id:name,age:30}}
function pixelAvatar(p){const key=(state?.seed||'LIGNEES')+'|portrait|'+(p.id||p.name),h=n=>Life.hash(key+'|'+n);const skin=['#f2c8a0','#dca270','#bc7e52','#99603f','#75452f','#5a352a'][Math.floor(h(1)*6)],light=['#ffdfb8','#efbd8f','#d7986e','#b77c53','#925f43','#774a35'][Math.floor(h(1)*6)],shadow=['#c68d68','#b1794d','#955b3a','#78452d','#573222','#42251c'][Math.floor(h(1)*6)];const age=p.age??30,hair=age>62?'#bdbdb1':['#302820','#534030','#8b623a','#b9834b','#292a29','#bba264'][Math.floor(h(2)*6)],cloth=['#8da97b','#8b93b9','#c18e80','#c0ac6e','#69a9a5','#ad8bab'][Math.floor(h(3)*6)],bg=['#2f402c','#303b42','#403a2d','#343b32'][Math.floor(h(4)*4)],long=h(5)>.55,beard=age>23&&p.sex==='M'&&h(6)>.6;let rects='';const r=(x,y,w,h,c)=>rects+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;r(0,0,24,24,bg);r(2,21,20,3,'#1c2a23');r(5,19,14,5,cloth);r(3,21,3,3,cloth);r(18,21,3,3,cloth);r(10,17,4,3,shadow);r(9,17,5,2,skin);if(long&&age>3)r(5,5,14,14,hair);r(6,7,12,9,skin);r(8,5,8,13,skin);r(7,7,8,8,light);r(5,10,2,4,skin);r(17,10,2,4,shadow);r(15,8,2,8,skin);r(16,10,1,5,shadow);if(age<3){r(9,5,5,1,hair);r(12,4,2,1,hair)}else{r(6,5,12,3,hair);r(8,4,8,2,hair);r(5,7,3,3,hair);r(15,7,3,long?7:3,hair);if(h(7)>.5)r(9,7,5,2,hair)}r(8,11,2,2,'#262a28');r(14,11,2,2,'#262a28');r(8,11,1,1,'#f7eedb');r(14,11,1,1,'#f7eedb');r(11,13,2,2,skin);r(10,16,4,1,shadow);r(10,15,3,1,'#cf8a72');if(beard){r(8,16,2,1,hair);r(9,17,6,1,hair);r(14,16,2,1,hair)}if(age>60){r(7,10,3,1,'#d5d1bf');r(14,10,3,1,'#d5d1bf')}if(h(8)>.65&&age>=12){r(7,10,4,1,'#47534b');r(7,13,4,1,'#47534b');r(13,10,4,1,'#47534b');r(13,13,4,1,'#47534b');r(7,10,1,4,'#47534b');r(16,10,1,4,'#47534b');r(10,11,4,1,'#47534b')}r(6,20,3,1,'#ffffff22');return`<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Portrait en pixel art de ${esc(p.name||'ce personnage')}" class="pixel-avatar ${p.alive===false?'deceased':''}" shape-rendering="crispEdges">${rects}</svg>`}
personRow=function(name,sub,button='',person=null){const p=person||avatarPerson(name.replace(/^↳ /,''));return`<div class="person"><div class="avatar pixel">${pixelAvatar(p)}</div><div><b>${esc(name)}</b><small>${esc(sub)}</small></div>${button}</div>`};
profile=function(){const p=state.person,c=Life.country(state);return`<section class="profile"><div class="avatar pixel">${pixelAvatar(p)}</div><div><h2>${esc(p.name)} ${esc(p.surname)}</h2><div class="meta"><span>⌖ ${esc(c.name)}</span><span>◌ ${p.age<5?'Les premières années':p.age<16?'Enfance & découvertes':esc(p.job)}</span><span>⑂ Génération ${state.generation}</span></div></div><div class="ageblock"><b>${p.age}</b> <span>ans</span><small>${state.year} · ${p.alive?'Une histoire en cours':'Une vie accomplie'}</small></div></section>`};
function nextUnlock(){return [5,6,8,16,18].find(n=>n>state.person.age)}
function yearHub(){const p=state.person;if(!p.alive)return'';if(p.age<5)return`<div class="childhood-note"><span>✦</span><p>Pour le moment, votre monde est celui des personnes qui prennent soin de vous. Regardez les mois défiler : les premiers souvenirs et les nouvelles possibilités arriveront avec l’âge.</p></div>`;const tips=[];
const add=(title,text,button,action,urgent=false)=>tips.push({title,text,button,action,urgent});
if(p.age>=18&&!p.career&&!p.retired)add('Une place dans le monde du travail',`Votre revenu salarial est nul. Explorez les offres de cette année sans quitter votre histoire.`,'Voir les offres',"openHubJobs()",true);
if(p.age>=18&&Life.finance(state).net<0)add('Le budget du foyer est déficitaire',`${plain(-Life.finance(state).net)} UPA manquent sur l’année estimée. Vos projets ont aussi leurs propres frais.`,'Ajuster mon budget',"openHubBudget()",true);
if(p.energy<35||p.stress>75)add('Votre équilibre réclame de l’attention',`Énergie ${Math.round(p.energy)}/100 · stress ${Math.round(p.stress)}/100.`,'Prendre du repos',"act('rest')",true);
if(p.partner&&p.partner.bond<45)add('Votre couple a besoin de présence',`${p.partner.name} garde le souvenir des tensions précédentes.`,'Écouter',`interact(${p.partner.id},'listen')`,true);
for(const x of p.projects){if(!x.paused&&x.funding!=='loan'&&p.cash<Life.projectCost(state,x))add(`${x.name} manque de financement`,'Sans liquidités suffisantes, ce projet attendra cette année.','Ajuster le rythme',`projectRhythm(${x.id})`,true)}
if(p.age>=16&&p.age<=40&&!p.scholarship&&p.projects.some(x=>['degree','training','retrain'].includes(x.type)))add('Financer votre formation autrement','Un dossier de bourse tient compte de votre parcours scolaire et des moyens de votre foyer.','Présenter un dossier',"act('scholarship')");
if(p.business&&p.business.cash<p.business.fixed*.6)add('La trésorerie de votre entreprise est fragile','Les charges fixes continuent même si les clients se font rares.','Renforcer la réserve',"businessFund()",true);
if(p.age>=6&&p.points>0){const sorted=Object.keys(p.skills).sort((a,b)=>p.skills[b]-p.skills[a]);add('Développer ce qui vous attire',`${Life.skills[sorted[0]]} est votre compétence la plus avancée. Vous pouvez la cultiver ou explorer autre chose.`,'Apprendre',"hubLearn()")}
if(p.age>=8&&p.projects.length<2&&p.points>0){const t=p.age<14?'language':p.age<18?'book':!p.education?'training':p.business?'community':'startup';add(p.projects.length?'Une envie de plus ?':'Un projet peut changer la suite',Life.templates[t].description,'Explorer mes projets',"hubProjects()")}
if(p.age>=18&&p.career&&p.career.years>=2&&p.career.level<3)add('Votre expérience peut ouvrir un cap',`${p.career.years} ans dans votre poste. Préparer la discussion peut vous donner l’avantage au D20.`,'Demander une promotion',"act('promotion')")
if(p.age>=18&&p.cash>Life.costs(state)*.5)add('Un peu de marge pour préparer la suite','Conserver une réserve ou investir expose votre avenir à des risques différents.','Investir une partie',"investment('funds','invest')");
if(p.age>=21&&p.age<=45&&p.partner?.wantsChildren&&p.partner.bond>=50&&p.children.length<3&&!p.actions.parentAttempt)add('Un projet parental à deux','Un enfant demande un accord, du temps et des ressources. Le désir ne garantit pas une naissance.','Envisager un enfant',"confirmChildProject()");
if(p.age>=5&&p.points>0)add('Les liens ont aussi besoin de temps',p.partner?`Un moment avec ${p.partner.name} et vos proches peut compter davantage qu’une nouvelle tâche.`:'Entretenir les liens et rencontrer de nouvelles personnes fait aussi partie d’une vie.','Voir mes proches',"act('social')")
return`<section class="year-hub"><div class="section-head"><h3>Cette année, l’essentiel est ici.</h3><span class="history-total">${p.points} créneau${p.points>1?'x':''} libre${p.points>1?'s':''}</span></div><div class="hub-cards">${tips.map(x=>`<article class="hub-card ${x.urgent?'attention':''}"><h4>${x.urgent?'<i class="dot"></i>':''}${esc(x.title)}</h4><p>${esc(x.text)}</p><button class="btn" onclick="${x.action}" ${!p.alive?'disabled':''}>${x.button} ↗</button></article>`).join('')}</div><p class="hint">Les décisions importantes et les étapes de vos projets arrivent automatiquement dans votre histoire. Les autres vues servent à approfondir.</p></section>`}
lifeView=function(){const s=state,p=s.person,n=Life.needs(s),next=nextUnlock();const moments=s.journal.filter(x=>x.person===p.id).slice(-7).reverse();const last=s.journal.filter(x=>x.kind==='instant'&&x.person===p.id&&x.year===s.year).at(-1);return`${heading(p.age<5?'Le monde s’ouvre, doucement.':p.age<18?'Devenir soi, une année après l’autre.':'Une vie, des choix qui se croisent.',p.age<5?'Vos premières années se racontent avant de se décider.':'Les événements et les possibilités utiles viennent à vous.',`<button class="pill" onclick="guide()">? &nbsp; Prendre en main</button>`)}${profile()}<div class="stats">${stat('Santé',Math.round(p.health)+' <em>/ 100</em>',p.health)}${stat('Épanouissement',Math.round(p.happiness)+' <em>/ 100</em>',p.happiness)}${stat('Énergie',Math.round(p.energy)+' <em>/ 100</em>',p.energy)}${p.age>=18?stat('Patrimoine net',money(p.alive?Life.balance(p):p.finalWorth||0)):stat('Stress',Math.round(p.stress)+' <em>/ 100</em>',100-p.stress)}</div>${last?`<div class="moment-card"><span class="eyebrow">${monthNames[(last.month||1)-1]} ${last.year} · Un instant de vie</span><p>${esc(last.text)}</p></div>`:''}${p.statuses.length?`<div class="status-strip">${p.statuses.map(x=>`<span class="tag warning">${esc(x.label)} · ${x.years} an(s)</span>`).join('')}</div>`:''}<div class="layout"><div>${!p.alive?ending():s.pending?eventView():''}${yearHub()}${p.projects.length?`<div class="card"><div class="section-head"><h3>Vos projets en cours</h3><button class="muted" onclick="hubProjects()">Les gérer ici ↗</button></div>${p.projects.map(miniProject).join('')}</div>`:''}<div class="section-head" style="margin-top:27px"><h3>Le fil de votre vie</h3><button class="muted" onclick="nav('journal')">Tout relire ↗</button></div>${timeline(moments)}</div><aside class="right">${p.age<6?`<div class="card"><h3>Votre premier univers</h3>${micro('Foyer',esc(p.birth.structure))}${micro('Cadre',p.birth.urban?'Milieu urbain':'Milieu rural')}${micro('Fratrie au départ',p.birth.siblings)}<div class="family-portraits">${p.parents.map((x,i)=>`<div><div class="avatar pixel">${pixelAvatar({...x,age:28+i*4})}</div><small>${esc(x.name)}</small></div>`).join('')}</div><p class="hint">Le foyer et l’environnement façonnent vos premières expériences. Vos propres choix prendront peu à peu plus de place.</p></div>`:`<div class="card"><h3>Ce que vous pouvez engager</h3><div class="time-blocks">${Array.from({length:Life.capacity(p)},(_,i)=>`<span class="${i<p.timeSpent?'spent':i<p.timeSpent+Life.projectEffort(p)?'reserved':'free'}"></span>`).join('')}</div>${micro('Disponible',Life.available(p)+' créneaux')}${micro('Réservé aux projets',Life.projectEffort(p)+' créneaux')}<label>Priorité de l’année</label><select aria-label="Priorité de l’année" onchange="act('focus',this.value)">${[['balance','Équilibre'],...(p.age>=18?[['career','Carrière & ambition']]:[]),['family','Proches & présence'],['health','Santé & récupération']].map(([v,t])=>`<option value="${v}" ${p.focus===v?'selected':''}>${t}</option>`).join('')}</select><p class="hint">Les actions utilisent du temps ; les projets en réservent chaque année. L’énergie et le stress limitent ce que vous pouvez soutenir.</p></div>`}${next?`<div class="card"><h3>La prochaine porte s’ouvrira à ${next} ans.</h3><p class="hint">${{5:'Vos relations prennent forme. L’école et les premiers choix arrivent.',6:'Vous pourrez apprendre, prendre des initiatives et développer vos habitudes.',8:'Vous pourrez commencer à construire des projets personnels.',16:'Les premières formations et les dossiers de bourse deviennent accessibles.',18:'Le travail, les finances, l’indépendance et les projets adultes vous attendent.'}[next]}</p></div>`:`<div class="card"><h3>Votre boussole : ${goalLabels[p.goal]}</h3>${[['security','Sécurité'],['freedom','Liberté'],['connection','Liens'],['meaning','Sens & création']].map(([k,t])=>`<div class="need"><span>${t}</span><div class="bar"><i style="width:${n[k]}%"></i></div><small>${Math.round(n[k])}</small></div>`).join('')}</div>`}<div class="card"><h3>Un monde qui évolue aussi</h3>${micro('Pays',esc(Life.country(s).name))}${micro('Époque',s.year)}${p.age>=16?micro('Conjoncture',phaseLabels[s.world.phase]):''}<p class="hint">Vous n’avez pas à surveiller chaque onglet : les tournants de votre vie et les alertes importantes apparaissent dans ce fil.</p></div></aside></div>`};
function confirmChildProject(){pauseClock();modal(`<h2>Un projet de famille ?</h2><p>Vous et ${esc(state.person.partner.name)} souhaitez avoir un enfant. La chance simulée d’une naissance pour cette tentative est de ${percent(Life.chance(state,'child'))}. Ce projet ne peut être engagé qu’une fois par année.</p><p>Un très jeune enfant réduit votre capacité de temps ; les dépenses du foyer augmentent aussi.</p><button class="btn primary" onclick="document.getElementById('modal').close();act('child')">Engager ce projet · 1 créneau</button>`)}
function hubLearn(){pauseClock();modal(`<h2>Qu’avez-vous envie d’apprendre ?</h2><p>Un créneau vous fait progresser dans une compétence. Les savoirs et l’expérience modifieront ensuite vos possibilités et vos bonus au D20.</p>${skillBars(state.person)}<div class="choices">${Object.entries(Life.skills).map(([k,t])=>`<button class="choice" onclick="document.getElementById('modal').close();act('learn','${k}')"><strong>${t}</strong><small>1 créneau</small></button>`).join('')}</div>`)}
function hubProjects(){pauseClock();const p=state.person;modal(`<h2>Vos projets, dans votre histoire.</h2>${p.projects.map(x=>`<div class="card">${miniProject(x)}${micro('Frais annuels',money(Life.projectCost(state,x)))}<div class="row"><button class="btn" onclick="projectRhythm(${x.id})">Rythme</button><button class="btn" onclick="act('projectPause',{id:${x.id}});hubProjects()">${x.paused?'Reprendre':'Pause'}</button><button class="btn danger" onclick="abandonProject(${x.id})">Abandonner</button></div></div>`).join('')}<div class="choices">${Object.entries(Life.templates).filter(([id,t])=>p.age>=t.minAge&&(!t.maxAge||p.age<=t.maxAge)&&!p.projects.some(x=>x.type===id)).map(([id,t])=>`<button class="choice" onclick="launchProject('${id}')"><span><strong>${t.name}</strong><small>${t.work} unités · ${money(Life.reference(state)*t.cost)} / année active</small></span><span>↗</span></button>`).join('')}</div>`)}
function openHubBudget(){pauseClock();const p=state.person,f=Life.finance(state);modal(`<h2>Rendre cette année soutenable.</h2>${micro('Liquidités',money(p.cash))}${micro('Revenus annuels du foyer',money(f.earnings))}${micro('Dépenses et charges',money(f.earnings-f.net))}${micro('Solde estimé',money(f.net))}<label for="hub-lifestyle">Niveau de vie</label><select id="hub-lifestyle" onchange="act('lifestyle',this.value);openHubBudget()">${[['frugal','Sobre'],['normal','Équilibré'],['comfort','Confortable']].map(([v,t])=>`<option value="${v}" ${p.lifestyle===v?'selected':''}>${t}</option>`).join('')}</select><div class="row"><button class="btn" onclick="document.getElementById('modal').close();act('gig')">Mission ponctuelle · 2</button><button class="btn" onclick="openHubJobs()">Chercher un poste</button><button class="btn" onclick="hubProjects()">Ajuster mes projets</button></div><p class="hint">Un déficit non financé finit dans la dette. Les projets de formation peuvent utiliser un prêt si vous l’avez autorisé.</p>`)}
function openHubJobs(){pauseClock();const p=state.person;modal(`<h2>Les possibilités de cette année.</h2><p>Vous gardez votre poste actuel en cas de refus. Les offres ne sont pas relancées en rouvrant ce panneau.</p><div class="choices">${Life.offers(state).map(o=>{const m=Life.checkModel(state,'job',o),locked=p.education<o.degree?'Qualification requise':p.actions[o.id]?'Candidature déjà envoyée':'';return`<button class="choice" ${locked?'disabled':''} onclick="document.getElementById('modal').close();act('applyJob','${o.id}')"><span><strong>${esc(o.title)}</strong><small>${money(o.salary)}/an · ${o.load===1?'temps partiel':o.load===3?'intensif':'temps plein'} · ${percent(m.probability)} au D20</small>${locked?`<small>${locked}</small>`:''}</span><span>⚄</span></button>`}).join('')}</div><button class="btn" onclick="act('prepare');openHubJobs()">Préparer mes entretiens · 1</button>`)}
// Projects are offered at the appropriate age, rather than exposing every adult option to a child.
const allProjectsView=projectsView;projectsView=function(){const count=Object.values(Life.templates).filter(t=>state.person.age>=t.minAge&&(!t.maxAge||state.person.age<=t.maxAge)).length;return allProjectsView().replace('12 parcours, plusieurs manières de les mener',count+' parcours accessibles à votre âge')};
let diceContext=null,diceInterval=null;
function diceForAction(type,value){if(type==='applyJob'){const offer=Life.offers(state).find(x=>x.id===value);return offer?Life.checkModel(state,'job',offer):null}if(['promotion','date','scholarship'].includes(type))return Life.checkModel(state,type);return null}
const actionBeforeDice=act;act=function(type,value){if(!state)return;const model=diceForAction(type,value);if(model){if(state.person.age<(type==='scholarship'?16:18)){toast('Cette possibilité arrive plus tard dans la vie.');return}pauseClock();openDice({kind:'action',type,value},model);return}actionBeforeDice(type,value)};
const decisionBeforeDice=decide;decide=function(index){const e=state?.pending,x=e?.choices[index];if(!x)return;const model=x.fx.roll?Life.checkModel(state,x.fx.roll):null;if(model){pauseClock();openDice({kind:'decision',index,eventId:e.id},model);return}const opens=x.fx.open;decisionBeforeDice(index);if(opens==='career'){pauseClock();openHubJobs()}};
function openDice(command,model){diceContext={command,model,rolled:false,finished:false};clearInterval(diceInterval);modal(`<div class="dice-heading"><div class="avatar pixel">${pixelAvatar(state.person)}</div><div><div class="eyebrow">Test de compétence · D20</div><h2>${esc(model.label)}</h2></div></div><div class="dice-stage"><svg class="d20" viewBox="0 0 160 180" role="img" aria-label="Dé à vingt faces"><path d="M80 5L150 45v90l-70 40-70-40V45Z" fill="#293c29" stroke="#bcdca0" stroke-width="2"/><path d="M80 5L40 60l40 65 40-65ZM10 45l30 15-30 75 70-10 70 10-30-75 30-15M40 60l80 0M80 125v50M10 135l30-75M150 135l-30-75" fill="none" stroke="#91aa7c" stroke-width="1.3"/><text id="dice-face" x="80" y="94" text-anchor="middle" fill="#e4f0d5" font-size="34" font-family="system-ui" font-weight="600">?</text></svg></div><div class="dice-formula"><b>${esc(model.formula)}</b><span>${percent(model.probability)} de réussite</span></div>${model.advantage!=='normal'?`<div class="advantage ${model.advantage==='advantage'?'positive':'negative'}">${model.advantage==='advantage'?'Avantage : 2 dés, le meilleur conservé. Votre préparation fait la différence.':'Désavantage : 2 dés, le moins bon conservé. Le stress ou l’épuisement pèse.'}</div>`:''}<div class="dice-modifiers">${model.bonuses.map(b=>`<div class="data-row"><span>${esc(b.label)}</span><b class="${b.value>0?'positive':b.value<0?'negative':''}">${b.context?'Difficulté accrue':(b.value>0?'+':'')+b.value}</b></div>`).join('')||'<p class="hint">Pas encore de bonus : l’apprentissage peut changer vos futurs tests.</p>'}${micro('Difficulté à atteindre',model.dc)}</div><div id="dice-outcome" class="dice-outcome"></div><button class="btn primary dice-roll-button" id="dice-button" onclick="rollDice()">Lancer le D20 →</button><p class="hint">Un 20 naturel est une réussite critique. Un 1 naturel est un échec critique. Le jet est enregistré une seule fois.</p>`)}
function rollDice(){if(!diceContext||diceContext.rolled)return;const ctx=diceContext,p=state.person,before=p.riskLog.length;ctx.rolled=true;let success=false,message='';if(ctx.command.kind==='action'){const r=Life.action(state,ctx.command.type,ctx.command.value);success=r.ok;message=r.message}else if(state.pending?.id===ctx.command.eventId){success=Life.choose(state,ctx.command.index);message=success?'Votre choix fait partie de votre histoire.':state.lastError}if(!success){diceContext=null;$('#modal').close();toast(message||'Ce choix n’est plus accessible.');return}const record=state.person.riskLog.length>before?state.person.riskLog.at(-1):null;if(!record?.check){diceContext=null;save();$('#modal').close();render();toast(message);return}ctx.result=record.check;ctx.message=message;ctx.resolved=record.result;save();render();const stage=document.querySelector('.dice-stage');if(stage)stage.classList.add('rolling-die');const button=document.getElementById('dice-button');if(button){button.textContent='Le dé roule…';button.disabled=true}let frames=0;const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){finishDice();return}diceInterval=setInterval(()=>{frames++;const node=document.getElementById('dice-face');if(node)node.textContent=String(1+Math.floor(Life.hash(state.seed+'|visual-dice|'+frames)*20));if(frames>=18)finishDice()},70)}
function finishDice(){if(!diceContext?.result||diceContext.finished)return;clearInterval(diceInterval);const ctx=diceContext,r=ctx.result;ctx.finished=true;const stage=document.querySelector('.dice-stage');if(stage)stage.classList.remove('rolling-die');const face=document.getElementById('dice-face');if(face)face.textContent=r.die;const out=document.getElementById('dice-outcome');if(out)out.innerHTML=`<strong class="${ctx.resolved?'positive':'negative'}">${r.critical==='success'?'20 naturel · Réussite critique !':r.critical==='failure'?'1 naturel · Échec critique.':ctx.resolved?'Le test est réussi.':'Le test échoue cette fois.'}</strong><p>${r.rolls.length>1?'Dés lancés : '+r.rolls.join(' et ')+' · ':''}${r.die} ${r.modifier>=0?'+':'−'} ${Math.abs(r.modifier)} = <b>${r.total}</b> · difficulté ${r.dc}</p><p>${esc(ctx.message)}</p>`;const button=document.getElementById('dice-button');if(button){button.disabled=false;button.textContent='Continuer mon histoire →';button.setAttribute('onclick','closeDice()')}}
function closeDice(){clearInterval(diceInterval);diceContext=null;$('#modal').close();render();if(clockWantResume&&!state.pending){clockWantResume=false;clockRunning=true;clockLast=performance.now();updateClockUI()}}
$('#modal').addEventListener('close',()=>{if(diceContext){clearInterval(diceInterval);diceContext=null;render()}});
const finishBirthBeforeAvatar=finishBirth;finishBirth=function(){finishBirthBeforeAvatar();const node=document.getElementById('birth-result');if(node&&!node.querySelector('.pixel-avatar'))node.insertAdjacentHTML('afterbegin',`<div class="birth-portrait avatar pixel">${pixelAvatar(state.person)}</div>`)};
const enhancedGuide=guide;guide=function(){enhancedGuide();const d=$('#modal');d.innerHTML+='<p><b>La vie se débloque avec l’âge :</b> relations à 5 ans, initiatives à 6 ans, projets à 8 ans, formations à 16 ans, carrière et finances à 18 ans.</p><p><b>Le D20 tient compte du passé :</b> compétences, diplôme, expérience, préparation et environnement. Une bonne préparation peut donner deux dés et conserver le meilleur ; l’épuisement peut produire l’inverse.</p><p><b>Restez dans Ma vie :</b> le tableau de bord rassemble les opportunités et les difficultés à traiter. Les onglets deviennent des outils de détail.</p>';};
if(state){Life.ensure(state);if(!unlockedTab(page))page='life'}render();
